import sys

def max_accordion_length(s):
    n = len(s)
    max_length = -1

    # Iterate over all possible starting positions of the accordion
    for start in range(n):
        if s[start] != '[':
            continue

        # Find the matching closing bracket
        end = start + 1
        open_brackets = 1
        while end < n and open_brackets > 0:
            if s[end] == '[':
                open_brackets += 1
            elif s[end] == ']':
                open_brackets -= 1
            end += 1

        if end == n or open_brackets != 0:
            continue

        # Check for valid accordion pattern
        colon_count = 0
        pipe_count = 0
        valid = True
        for i in range(start + 1, end - 1):
            if s[i] == ':':
                colon_count += 1
            elif s[i] == '|':
                if colon_count != 1:
                    valid = False
                    break
                pipe_count += 1
            else:
                valid = False
                break

        if valid and colon_count == 2:
            max_length = max(max_length, end - start)

    return max_length

# Read input
s = sys.stdin.read().strip()

# Output the result
print(max_accordion_length(s))
